import indexableProducts from '@/data/indexable-products.json'

const CATALOG_PRODUCT_BASE = 'https://domexpertmebel.com/каталог/'

/**
 * Representative product slug per indexable catalog model, generated by
 * scripts/generate-indexable-products.mjs (npm run catalog:indexable).
 */
const representativeByModel = new Map(
  indexableProducts.models.map((model) => [model.key, model.slug]),
)

function getModelKey(product: { itemGroupId: string; itemId: string }) {
  const groupId = product.itemGroupId.trim()
  return groupId ? `group:${groupId}` : `item:${product.itemId.trim()}`
}

/** Slug of the indexed URL for this product's model, or undefined when the model stays noindex. */
export function getIndexableRepresentativeSlug(product: { itemGroupId: string; itemId: string }) {
  return representativeByModel.get(getModelKey(product))
}

export function isIndexableRepresentative(product: { itemGroupId: string; itemId: string; slug: string }) {
  return getIndexableRepresentativeSlug(product) === product.slug
}

export function getCatalogProductUrl(slug: string) {
  return CATALOG_PRODUCT_BASE + slug + '/'
}

export const indexableProductSlugs = indexableProducts.models.map((model) => model.slug)
